pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new C();
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.prank(owner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(c.owner() != address(0), "owner must never be zero after a successful transferOwnership");
        } else {
            assertTrue(true, "call reverted, no rule violated");
        }
    }
}

