// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); c.initialize(); }
    function testFuzz_property(address newImplementation) public {
        // owner is address(this) (the deployer); no narrowing of the fuzzed address,
        // so address(0) remains in the admissible domain.
        bool ok;
        vm.prank(address(this));
        try c.updateRoundImplementation(payable(newImplementation)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a successful updateRoundImplementation never leaves a
        // zero roundImplementation (either it reverts on zero, or stores a non-zero target).
        assertTrue(!ok || c.roundImplementation() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address actor, address newImpl) public {
        // owner is the deployer (this contract); allow any caller but prank the actor
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: an update either reverts, or (when authorized) succeeds and
        // the stored implementation is a real (non-zero) address matching the input.
        // The mutant accepts address(0), succeeding with a stored zero address.
        assertTrue(!(ok && newImpl == address(0)) && (!ok || c.roundImplementation() == newImpl));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        // Wide domain: the fuzzer may supply ANY address, including address(0).
        // Only the owner (the deployer, which is this test contract) may call.
        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a successful update must store a NON-ZERO round implementation.
        // Reference: reverts on address(0) (ok == false). Mutant: succeeds with address(0),
        // leaving c.roundImplementation() == address(0) after a successful call.
        assertTrue(!(ok && c.roundImplementation() == address(0)));
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address payable newImpl) external {
        require(newImpl != address(0), "impl must be nonzero");

        bytes memory data = abi.encodeWithSelector(
            c.updateRoundImplementation.selector,
            newImpl
        );
        bool ok;
        (ok, ) = address(c).call(data);

        assert(
            !ok || (c.roundImplementation() == newImpl && c.owner() == msg.sender)
        );
    }
}
